18	// Rust: use u128 in case someone want to use someday
19	fn gen_value_bit_entry(bit_entry: &[bool], max_bit_entry: usize) -> u128 {
20	    let mut bitmap_int: u128 = 0;
21	    for i in 0..max_bit_entry {
22	        bitmap_int <<= 1;
23	
24	        if let Some(t) = bit_entry.get(i) {
