//! generate_uri_snmp_table in 3rdparty_net_snmp

use std::env;
use std::fs::{self, remove_file, File, OpenOptions};
use std::io::Write;
use std::path::Path;
use std::process::exit;

use lib_moxa_rust_iss::interface_utility::InterfaceType;

// Rust: use u128 in case someone want to use someday
fn gen_value_bit_entry(bit_entry: &[bool], max_bit_entry: usize) -> u128 {
    let mut bitmap_int: u128 = 0;
    for i in 0..max_bit_entry {
        bitmap_int <<= 1;

        if let Some(t) = bit_entry.get(i) {
            if *t {
                bitmap_int |= 0x1;
            }
        } else {
            // pass
        }
        // #print( str(i) + ":" + "%08x" % bitmap_int )
    }

    bitmap_int
}

#[allow(dead_code)] // for function gen_value_days_of_work_entry
fn gen_value_days_of_work_entry(value_entry: &[bool]) -> String {
    let bitmap_int = gen_value_bit_entry(value_entry, 8);
    format!("{bitmap_int:01x}")
}

#[cfg(feature = "MOXA_DHCP_SERVER_OPTION_121")]
fn gen_value_port_entry(value_entry: &[bool]) -> String {
    let bitmap_int = gen_value_bit_entry(value_entry, 64);
    format!("{bitmap_int:016x}")
}

fn gen_value_redundant_port_entry(
    max_port_num: u32,
    first_port_iftype: u64,
    first_port_index: u32,
    second_port_iftype: u64,
    second_port_index: u32,
) -> String {
    let mut first_port = first_port_index + 1;
    if first_port_iftype == InterfaceType::PortChannel as u64 {
        first_port += max_port_num;
    }

    let mut second_port = second_port_index + 1;
    if second_port_iftype == InterfaceType::PortChannel as u64 {
        second_port += max_port_num;
    }

    format!("{first_port:02x}{second_port:02x}")
}

fn gen_value_mirror_port_tbl_entry(port_table: &serde_json::Value) -> String {
    let mut port_str = "".to_owned();
    for port in port_table.as_array().unwrap() {
        port_str = format!("{port_str}{:02x}", port.as_u64().unwrap());
    }

    port_str
}

fn gen_value_mirror_port_str_entry(max_port_num: u32, port_bitstr: &serde_json::Value) -> String {
    let port_bitstr = port_bitstr.as_str().unwrap();

    let mut port_str = "".to_owned();

    for port in 0..max_port_num {
        if port_bitstr.chars().nth(port as usize).unwrap() == '1' {
            port_str = format!("{port_str}{:02x}", port + 1);
        }
    }

    port_str
}

#[cfg(feature = "MOXA_DRC")]
fn gen_value_coupling_port_entry(max_port_num: u32, port_iftype: u64, port_index: u32) -> String {
    if port_iftype == 0 {
        return "00".to_string();
    }

    let mut port = port_index + 1;
    if port_iftype == InterfaceType::PortChannel as u64 {
        port += max_port_num;
    }

    format!("{port}")
}

fn gen_value_turth_value(value_entry: &serde_json::Value) -> char {
    let value_entry = value_entry.as_bool().unwrap();

    if value_entry {
        '1'
    } else {
        '2'
    }
}

/*
def genValue_BITsFor2OCTs(value_entry):
    bitmap_int = int(value_entry, base=16)
    ret_int = 0x0
    if bitmap_int & 0x80:
        ret_int |= 0x1
    if bitmap_int & 0x40:
        ret_int |= 0x2
    if bitmap_int & 0x20:
        ret_int |= 0x4
    if bitmap_int & 0x10:
        ret_int |= 0x8
    if bitmap_int & 0x8:
        ret_int |= 0x10
    if bitmap_int & 0x4:
        ret_int |= 0x20
    if bitmap_int & 0x2:
        ret_int |= 0x40
    if bitmap_int & 0x1:
        ret_int |= 0x80
    return "%x" % ret_int
*/

fn gen_value_row_status_field_turth_value(value_entry: &serde_json::Value) -> char {
    if value_entry.is_null() {
        '2'
    } else {
        gen_value_turth_value(value_entry)
    }
}

fn gen_value_row_status_field_ipaddress(value_entry: &serde_json::Value) -> String {
    if value_entry.is_null() {
        "0.0.0.0".to_owned()
    } else {
        value_entry.as_str().unwrap().to_owned()
    }
}

fn gen_value_row_status_field_mac_address(value_entry: &serde_json::Value) -> String {
    if value_entry.is_null() || !value_entry.is_string() {
        "000000000000".to_owned()
    } else {
        value_entry.as_str().unwrap().to_owned()
    }

