fn generate_snmp_trap_host(iput_json: &serde_json::Value, oput_file: &mut File, oput_uptime: &str) {
    let uri_oid_str = "1.3.6.1.4.1.8691.602.7.2.1.3.1"; // From MIB
    let uri_table_range = iput_json.as_array().unwrap().len();
    let mut oid_index = 0;

    // Uptime
    writeln!(oput_file, "#uptime={}", oput_uptime).unwrap();

    // index
    oid_index += 1;
    for i in 0..uri_table_range {
        writeln!(
            oput_file,
            "{}.{}.{}='{}'",
            uri_oid_str,
            oid_index,
            i + 1,
            i + 1,
        )
        .unwrap();
    }

    // hostName
    oid_index += 1;
    for i in 0..uri_table_range {
        writeln!(
            oput_file,
            "{}.{}.{}='{}'",
            uri_oid_str,
            oid_index,
            i + 1,
            gen_value_row_status_field_string(&iput_json[i]["hostName"])
        )
        .unwrap();
    }

    // mode
    oid_index += 1;
    for i in 0..uri_table_range {
        writeln!(
            oput_file,
            "{}.{}.{}='{}'",
            uri_oid_str,
            oid_index,
            i + 1,
            gen_value_row_status_field_number(&iput_json[i]["mode"])
        )
        .unwrap();
    }
    // status
    oid_index += 1;
    for i in 0..uri_table_range {
        writeln!(
            oput_file,
            "{}.{}.{}='{}'",
            uri_oid_str,
            oid_index,
            i + 1,
            gen_value_io_power_poe_status(&iput_json[i]["status"])
        )
        .unwrap();
    }
}

